int main(int argc, char* argv[])
{
    int error;

    if (argc <= 1) {
        printf("Usage: ini_dump filename.ini\n");
        return 1;
    }

    error = ini_parse(argv[1], dumper, NULL);
    if (error < 0) {
        printf("Can't read '%s'!\n", argv[1]);
        return 2;
    }
    else if (error) {
        printf("Bad config file (first error on line %d)!\n", error);
        return 3;
    }
    return 0;
}
